import os
import logging
import subprocess
import pysftp
import time

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SwHandler(object):
    def download_build_from_wft(self, version,
                                directory='/home/localuser',
                                url='https://artifactory-espoo1.ext.net.nokia.com/artifactory/'
                                    + 'mnp5g-central-public-local/System_Release'):
        """
        Download Build from artifactory and store it to the specified dir

        :param version: Build version: e.g 5.3135.866
        :param directory: by default /home/localuser
        :param url: url to the artifactory directory by Default
         https://artifactory-espoo1.ext.net.nokia.com/artifactory/mnp5g-central-public-local/System_Release

        :return: path to Build
        """

        if not os.path.exists(directory):
            logger.error('directory doesn\'t exist ')
            raise ValueError
        logger.info("Downloading Build {}".format(version))
        _command = 'wget --no-check-certificate ' + '-P ' + str(directory) + ' ' + str(url) + '/' + str(version) + \
                   '/' + 'AirScale-' + str(version) + \
                   '.zip'
        try:
            subprocess.check_output(_command,
                                    stderr=subprocess.STDOUT,
                                    shell=True)
        except subprocess.CalledProcessError as e:
            raise RuntimeError("command '{}' return with error (code {}): {}".format(e.cmd, e.returncode, e.output))
        while not os.path.exists(str(directory) + '/AirScale-' + str(version) + '.zip'):
            time.sleep(30)

        if os.path.isfile(str(directory) + '/AirScale-' + str(version) + '.zip'):
            logger.info('Build {} downloaded successfully'.format(version))
            return str(directory) + '/AirScale-' + str(version) + 'zip'
        else:
            return ('download Failure load {} isn\'t properly downloaded'.format(str(version)))

    def send_build_to_remote(self, remote, host, password, path_to_file, path_on_remote):
        """
        send File from host to remote

        :param remote: remote machine address
        :param host: username for connection session
        :param password: password for connection session
        :param path_to_file: the file path on the host machine
        :param path_on_remote: path where the file should be stored on remote machine

        :return: file path on remote
        """
        if not os.path.exists(path_to_file):
            logger.error('File not found, verify path')
            raise ValueError
        with pysftp.Connection(remote, username=host, password=password) as sftp:
            logger.info('sending file {} to remote {}'.format(path_to_file, remote))
            with sftp.cd(path_on_remote):
                sftp.put(path_to_file)
                logger.info('file sent')
        return str(path_on_remote) + str(path_to_file.split('/')[-1])
